    static int shortestPath(int[][] grid, int k) {
        int m = grid.length, n = grid[0].length;
        if (m == 1 && n == 1) return 0;
        k = Math.min(k, m + n - 2);

        Set<Integer> visited = new HashSet<>();
        visited.add(encode(0, 0, k, n));
        Queue<int[]> queue = new LinkedList<>();
        queue.add(new int[]{0, 0, k});
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        int steps = 0;

        while (!queue.isEmpty()) {
            steps++;
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int[] cur = queue.poll();
                int r = cur[0], c = cur[1], rem = cur[2];
                for (int[] d : dirs) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
                    int newRem = rem - grid[nr][nc];
                    if (newRem < 0) continue;
                    if (nr == m - 1 && nc == n - 1) return steps;
                    int state = encode(nr, nc, newRem, n);
                    if (visited.contains(state)) continue;
                    visited.add(state);
                    queue.add(new int[]{nr, nc, newRem});
                }
            }
        }
        return -1;
    }

    static int encode(int r, int c, int rem, int n) {
        return (r * n + c) * 100 + rem;
